<?php /** Template Name: Producer Portal */ if(!defined('ABSPATH'))exit;if(!is_user_logged_in()){wp_safe_redirect(wp_login_url(home_url('/producer-portal/')));exit;}if(!tuff_beatz_is_producer_user()){wp_safe_redirect(home_url('/client-portal/'));exit;}$q=new WP_Query(array('post_type'=>'tb_request','post_status'=>'publish','posts_per_page'=>100,'orderby'=>'date','order'=>'DESC'));$projects=$q->posts;$counts=array('new'=>0,'reviewing'=>0,'approved'=>0,'in-progress'=>0,'revision'=>0,'mastering'=>0,'delivery'=>0,'completed'=>0);foreach($projects as $p){$s=get_post_meta($p->ID,'_tb_request_status',true)?:'new';if(isset($counts[$s]))$counts[$s]++;}get_header();?>
<main class="tb-hub tb-producer-hub"><section class="tb-hub-hero"><div class="container"><p class="eyebrow">TUFF BEATZ PRODUCER PORTAL</p><h1>Production Command Center</h1><p>Manage every client, project, file, review, contract, payment and deadline from one workspace.</p><div class="tb-hub-actions"><a class="btn btn-gold" href="<?php echo esc_url(home_url('/producer-crm/'));?>">Client CRM</a><a class="btn btn-outline" href="<?php echo esc_url(admin_url('edit.php?post_type=tb_request'));?>">WordPress Project Admin</a><a class="btn btn-outline" href="<?php echo esc_url(home_url('/start-a-project/'));?>">Open Intake Portal</a></div></div></section>
<section class="section"><div class="container"><div class="tb-stat-grid"><div><small>NEW</small><strong><?php echo esc_html($counts['new']);?></strong></div><div><small>IN PRODUCTION</small><strong><?php echo esc_html($counts['in-progress']);?></strong></div><div><small>REVISION</small><strong><?php echo esc_html($counts['revision']);?></strong></div><div><small>MASTERING</small><strong><?php echo esc_html($counts['mastering']);?></strong></div><div><small>DELIVERY</small><strong><?php echo esc_html($counts['delivery']);?></strong></div><div><small>COMPLETED</small><strong><?php echo esc_html($counts['completed']);?></strong></div></div><div class="tb-hub-heading"><div><p class="tb-card-kicker">ALL ACTIVE WORK</p><h2>Production Projects</h2></div><span><?php echo esc_html(count($projects));?> total</span></div><?php if($projects):?><div class="tb-producer-list"><?php foreach($projects as $p):$id=$p->ID;$status=get_post_meta($id,'_tb_request_status',true)?:'new';$service=get_post_meta($id,'_tb_request_service',true);$artist=get_post_meta($id,'_tb_request_artist',true);$email=get_post_meta($id,'_tb_request_email',true);$progress=tuff_beatz_project_progress_percent($id);$services=tuff_beatz_services();?><article class="tb-producer-row"><div class="tb-producer-main"><span class="tb-status tb-status--<?php echo esc_attr($status);?>"><?php echo esc_html(tuff_beatz_request_status_label($status));?></span><div><h3><?php echo esc_html($p->post_title);?></h3><p><?php echo esc_html($artist?:'Client');?> • <?php echo esc_html($services[$service]??$service);?> • <?php echo esc_html($email);?></p></div></div><div class="tb-producer-progress"><small>PROGRESS</small><strong><?php echo esc_html($progress);?>%</strong><div class="tb-progress"><i style="width:<?php echo esc_attr($progress);?>%"></i></div></div><div class="tb-producer-actions"><a href="<?php echo esc_url(tuff_beatz_project_dashboard_url($id));?>">Open Workspace</a><a href="<?php echo esc_url(admin_url('post.php?post='.$id.'&action=edit'));?>">Manage Project</a></div></article><?php endforeach;?></div><?php else:?><div class="tb-empty-hub"><h3>No project requests yet</h3><p>New submissions will appear here automatically.</p></div><?php endif;?></div></section></main><?php get_footer();?>